const char *typeName = GetTypeName<float_test_type>();

SetFunctionName("Floor(%s)", typeName);
Validate(Floor((float_test_type)3.9f) == (float_test_type)3.f);
Validate(Floor((float_test_type)2.5f) == (float_test_type)2.0f);
Validate(Floor((float_test_type)3.5f) == (float_test_type)3.0f);
Validate(Floor((float_test_type)1.01f) == (float_test_type)1.0f);
Validate(Floor((float_test_type)-3.9f) == (float_test_type)-4.f);
Validate(Floor((float_test_type)-2.5f) == (float_test_type)-3.0f);
Validate(Floor((float_test_type)-1.01f) == (float_test_type)-2.0f);

// Ensure large numbers Floor properly.
Validate(Floor((float_test_type)2.5521178e38f) == (float_test_type)2.5521178e38f);
Validate(Floor((float_test_type)-2.5521178e38f) == (float_test_type)-2.5521178e38f);

// Check a range of numbers around 0
bool success = true;
const int numDivisions = 100;
for(int rangeStart = -10; rangeStart < 10; rangeStart++)
{
    for(int division=0; division<numDivisions; division++)
    {
        float value = ((float)rangeStart) + ((float)division) / ((float)numDivisions);
        success &= ( Floor((float_test_type)value) == (float_test_type)(float)rangeStart );
    }
}
Validate(success);



