            bool passCondition = IsEqualWithinPercent(Exp((float_test_type)exp_values[i].input), (float_test_type)exp_values[i].output, (float_test_type)0.00001f) ||
                                 IsEqualWithEpsilon(Exp((float_test_type)exp_values[i].input), (float_test_type)exp_values[i].output, (float_test_type)FEXP_EPSILON);
            Validate(passCondition);
#else
            Validate(IsEqualWithEpsilon(Exp((float_test_type)exp_values[i].input),
                (float_test_type)exp_values[i].output, (float_test_type)FEXP_EPSILON));
#endif
        }



for (int i = 0; i < NUM_SQRT_VALUES; ++i)
{
    SetFunctionName("Sqrt test[%d]", i);
    Validate(IsEqualWithEpsilon(Sqrt((float_test_type)sqrt_values[i].input),
        (float_test_type)sqrt_values[i].output, (float_test_type)FSQRT_EPSILON));
}



