const char *typeName = GetTypeName<float_test_type>();

SetFunctionName("              Sum negatives and positives using Select", typeName);

StartTimer(testing::RW_MATH_UNITTEST_TEST_VECTOR_ARRAY_SIZE * testing::RW_MATH_UNITTEST_TEST_LOOP_COUNT_LONG);

float_test_type zero(0.0f);
float_test_type positiveSum(zero);
float_test_type negativeSum(zero);
for (int testloop = 0; testloop < testing::RW_MATH_UNITTEST_TEST_LOOP_COUNT_LONG; testloop++)
{
    for (int i = 0; i < testing::RW_MATH_UNITTEST_TEST_VECTOR_ARRAY_SIZE; i++)
    {
        MaskScalar positiveMask = CompGreaterEqual(xArray[i], zero);
        positiveSum += Select( positiveMask, xArray[i], zero );
        negativeSum += Select( positiveMask, zero, xArray[i] );
    }
    // Make sure results are used so the compiler calculates them.
    fOutArray[0] += positiveSum;
    fOutArray[1] += negativeSum;
}

StopTimer();



const char *typeName = GetTypeName<float_test_type>();

SetFunctionName("Unrolled (x4) Sum negatives and positives using Select", typeName);

StartTimer(testing::RW_MATH_UNITTEST_TEST_VECTOR_ARRAY_SIZE * testing::RW_MATH_UNITTEST_TEST_LOOP_COUNT_LONG);

float_test_type zero(0.0f);
float_test_type positiveSum0(zero);
float_test_type positiveSum1(zero);
float_test_type positiveSum2(zero);
float_test_type positiveSum3(zero);
float_test_type negativeSum0(zero);
float_test_type negativeSum1(zero);
float_test_type negativeSum2(zero);
float_test_type negativeSum3(zero);
for (int testloop = 0; testloop < testing::RW_MATH_UNITTEST_TEST_LOOP_COUNT_LONG; testloop++)
{
    for (int i = 0; i < testing::RW_MATH_UNITTEST_TEST_VECTOR_ARRAY_SIZE; i+=4)
    {
        MaskScalar positiveMask0 = CompGreaterEqual(xArray[i+0], zero);
        positiveSum0 += Select( positiveMask0, xArray[i+0], zero );
        negativeSum0 += Select( positiveMask0, zero, xArray[i+0] );

        MaskScalar positiveMask1 = CompGreaterEqual(xArray[i+1], zero);
        positiveSum1 += Select( positiveMask1, xArray[i+1], zero );
        negativeSum1 += Select( positiveMask1, zero, xArray[i+1] );

        MaskScalar positiveMask2 = CompGreaterEqual(xArray[i+2], zero);
        positiveSum2 += Select( positiveMask2, xArray[i+2], zero );
        negativeSum2 += Select( positiveMask2, zero, xArray[i+2] );

        MaskScalar positiveMask3 = CompGreaterEqual(xArray[i+3], zero);
        positiveSum3 += Select( positiveMask3, xArray[i+3], zero );
        negativeSum3 += Select( positiveMask3, zero, xArray[i+3] );
    }
    // Make sure results are used so the compiler calculates them.
    fOutArray[0] += positiveSum0 + positiveSum1 + positiveSum2 + positiveSum3;
    fOutArray[1] += negativeSum0 + negativeSum1 + negativeSum2 + negativeSum3;
}

StopTimer();



